import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';

import { ChevronLeft, Triangle, ArrowUp, ArrowDown } from 'lucide-react';
import {AreaChart,Area,XAxis,YAxis,CartesianGrid,ResponsiveContainer} from 'recharts';

// --- モックデータ ---
const data = [
  { name: '第1号', blue: 1.2, orange: 2.0 },
  { name: '第2号', blue: 1.5, orange: 1.8 },
  { name: '第2号', blue: 1.1, orange: 2.3 },
  { name: '第3号', blue: 1.5, orange: 2.0 },
  { name: '第3号', blue: 1.1, orange: 1.8 },
  { name: '第4号', blue: 2.0, orange: 2.6 },
  { name: '第5号', blue: 1.5, orange: 2.1 },
  { name: '第5号', blue: 2.2, orange: 2.8 },
];

type RankingRow = {
  issue_label: string;
  title: string;
  rank_num: number;
};

interface Work {
  id: number;
  work_id: number;
  title: string;
  title_kana: string;
  title_eng: string;
  author: string;
  serialization_start_date: string;
  end_flg: boolean;
  story: string;
  genre: string;
  created_at: string;
  updated_at: string;
  peak_rank: number;
  status: string;
  image_url: string;
  official_url: string;
};

interface Volume {
  volume: number;
  releaseDate: string;
  coverimage: string;
  price: number;
  isbn: string;
  description: string;
  pages: number;
}

interface RankingData {
  title: string;
  [key: string]: string | number;
}

const DetailPage = () => {
  const [searchParams] = useSearchParams();
  const [mangaDetail, setMangaDetail] = useState<Work | null>(null);
  const [volumes, setVolumes] = useState<Volume[]>([]);
  const [rankingData, setRankingData] = useState<RankingData[]>([]);
  //const [data, setData] = useState<RankingRow[]>([]);
  const [loading, setLoading] = useState(true);
  const title = searchParams.get('title');



  return (
    /* 全体のコンテナ：背景色を強制的に指定 */
    <div style={{
      backgroundColor: '#1b2230',
      color: '#ffffff',
      minHeight: '100vh',
      width: '100%',
      maxWidth: '400px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'sans-serif'
    }}>

      {/* ヘッダー */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '24px' }}>
        <ChevronLeft size={24} color="#94a3b8" />
        <h1 style={{ fontSize: '18px', fontWeight: 'bold', letterSpacing: '0.2em', margin: 0 }}>ONE PIECE</h1>
        <div style={{ width: '24px' }} />
      </div>

      {/* 4つのカードセクション */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '8px', marginBottom: '32px' }}>
        <StatBox title="最新順位" value="1" unit="位" color="#2a5496" />
        <StatBox title="平均順位" value="2.4" unit="位" color="#2d5a50" icon={<Triangle size={8} fill="#4ade80" color="#4ade80" />} />
        <StatBox title="最高順位" value="1" unit="位" color="#252b39" border="1px solid #334155" icon={<ArrowUp size={12} fill="#ef4444" color="#ef4444" />} />
        <StatBox title="最低順位" value="6" unit="位" color="#252b39" border="1px solid #334155" icon={<ArrowDown size={12} fill="#ef4444" color="#ef4444" />} />
      </div>

      {/* グラフエリア */}
      <div style={{ marginBottom: '32px' }}>
        <h2 style={{ fontSize: '14px', borderBottom: '1px solid #334155', paddingBottom: '4px', marginBottom: '16px' }}>順位推移</h2>
        <div style={{ height: '200px', width: '100%' }}>
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={data} margin={{ top: 10, right: 10, left: -40, bottom: 0 }}>
              <defs>
                <linearGradient id="gradBlue" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#60a5fa" stopOpacity={0.4}/>
                  <stop offset="100%" stopColor="#60a5fa" stopOpacity={0}/>
                </linearGradient>
                <linearGradient id="gradOrange" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#f87171" stopOpacity={0.4}/>
                  <stop offset="100%" stopColor="#f87171" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid vertical={false} stroke="#334155" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} interval={1} />
              <YAxis reversed domain={[1, 3]} hide />

              <Area type="monotone" dataKey="orange" stroke="#f87171" fill="url(#gradOrange)" strokeWidth={2} dot={{ r: 4, fill: '#fff', stroke: '#f87171' }} />
              <Area type="monotone" dataKey="blue" stroke="#60a5fa" fill="url(#gradBlue)" strokeWidth={2} dot={{ r: 4, fill: '#fff', stroke: '#60a5fa' }} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* 下部のリスト */}
      <div>
        <h2 style={{ fontSize: '14px', marginBottom: '12px' }}>号別順位</h2>
        <ListRow label="第10号" value="1" />
        <ListRow label="第9号" value="2" />
        <ListRow label="第8号" value="3" />
      </div>
    </div>
  );
};

// --- スタイル付きサブコンポーネント ---

const StatBox = ({ title, value, unit, color, border, icon }: any) => (
  <div style={{
    backgroundColor: color,
    border: border || 'none',
    borderRadius: '4px',
    padding: '8px',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'space-between',
    alignItems: 'center',
    aspectRatio: '1/1'
  }}>
    <div style={{ fontSize: '9px', opacity: 0.8, textAlign: 'center' }}>{title}</div>
    <div style={{ display: 'flex', alignItems: 'baseline', gap: '2px' }}>
      <span style={{ fontSize: '20px', fontWeight: 'bold', fontStyle: 'italic' }}>{value}</span>
      <span style={{ fontSize: '10px' }}>{unit}</span>
      {icon && <span style={{ marginLeft: '2px' }}>{icon}</span>}
    </div>
  </div>
);

const ListRow = ({ label, value }: any) => (
  <div style={{
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '12px 0',
    borderBottom: '1px solid rgba(255,255,255,0.1)'
  }}>
    <span style={{ color: '#94a3b8', fontSize: '14px' }}>{label}</span>
    <div style={{ display: 'flex', alignItems: 'baseline', gap: '2px' }}>
      <span style={{ fontSize: '18px', fontWeight: 'bold', fontStyle: 'italic' }}>{value}</span>
      <span style={{ fontSize: '10px', fontWeight: 'bold' }}>位</span>
    </div>
  </div>
);

export default DetailPage;
